using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using RingTimer;
// Scripted native WPF rendering on a controlled backdrop; all data is a fixture.
class ShowcaseCapture {
 static MenuWindow menu;static Bubble bubble;static string output;
 static void Pump(int ms){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 static IEnumerable<T> All<T>(DependencyObject n) where T:DependencyObject{if(n is T)yield return (T)n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var v in All<T>(VisualTreeHelper.GetChild(n,i)))yield return v;}
 static void Save(string name){menu.UpdateLayout();int w=(int)Math.Ceiling(menu.ActualWidth),h=(int)Math.Ceiling(menu.ActualHeight);var native=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);native.Render(menu);var composition=new DrawingVisual();using(var dc=composition.RenderOpen()){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(14,18,24)),null,new Rect(0,0,w,h));dc.DrawImage(native,new Rect(0,0,w,h));if(!menu.CardPresenter.IncludesLauncher){var m=menu.PixelBounds;var b=bubble.PixelBounds;double dpi=Native.ScaleFor(menu.Handle);dc.DrawRectangle(new VisualBrush((Visual)bubble.Content),null,new Rect((b.Left-m.Left)/dpi,(b.Top-m.Top)/dpi,44,44));}}var image=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);image.Render(composition);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));string file=Path.Combine(output,name+".png");Directory.CreateDirectory(Path.GetDirectoryName(file));using(var s=File.Create(file))encoder.Save(s);}
 [STAThread]static void Main(string[] args){Native.SetProcessDPIAware();output=args[0];var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var preferences=new AppearanceSettings(null);try{
 Theme.ApplyGlobalResources(app);preferences.Language="en";Theme.Apply(true,null,null,null);var engine=new TimerEngine(new TimerState(),()=>DateTime.UtcNow);engine.ConfigureCycle(1500,480,1);var timer=new TimerFeature(engine,()=>{});var context=new ContextFeature();context.Update(new ContextUsage{Known=true,Used=38000,Capacity=100000});menu=new MenuWindow(new FeatureRegistry(context,new StatsFeature(new StatsStore(null)),timer),()=>{},()=>{},preferences){Left=-2200,Top=0,AnimationsEnabled=false};menu.OpenFeature("timer");menu.Reveal();Pump(150);bubble=new Bubble();bubble.Show();var m=menu.PixelBounds;var b=bubble.PixelBounds;double dpi=Native.ScaleFor(menu.Handle);bubble.MovePixels(m.Right-(int)(Theme.LauncherDockInset*dpi)-b.Width,m.Bottom-(int)(Theme.LauncherDockInset*dpi)-b.Height);bubble.SetContext(new ContextUsage{Known=true,Used=38000,Capacity=100000});menu.Launcher=bubble;menu.AnchorBounds=()=>bubble.PixelBounds;menu.RestoreCardContour();Pump(80);
 var atmosphere=All<CardAtmosphere>(menu).Single();var rotation=(RotateTransform)((ImageBrush)All<Border>(atmosphere).First(x=>x.BorderBrush is ImageBrush).BorderBrush).Transform;
 for(int i=0;i<240;i++){rotation.Angle=45+i*1.5;Save("rotation/"+i.ToString("D3"));}rotation.Angle=45;Save("timer-dark");Theme.Apply(false,null,null,null);Pump(80);Save("timer-light");Theme.Apply(true,null,null,null);Pump(80);rotation=(RotateTransform)((ImageBrush)All<Border>(atmosphere).First(x=>x.BorderBrush is ImageBrush).BorderBrush).Transform;
 menu.AnimationsEnabled=true;atmosphere.SetMotion(false);
 for(int i=0;i<150;i++){if(i==12)menu.CardPresenter.Begin(new Point(180,250));if(i>=12&&i<105){double a=(i-12)/92.0*Math.PI*2;menu.CardPresenter.Move(new Point(180+240*Math.Sin(a),250-210*Math.Cos(a)));}if(i==105)menu.CardPresenter.Release();rotation.Angle=45+i*1.5;Pump(50);Save("tilt/"+i.ToString("D3"));}
 for(int i=0;i<100;i++){if(i==8)timer.Panel.OpenEditor("work");if(i==36)timer.Panel.CancelEditor();if(i==52)timer.Panel.OpenEditor("rest");if(i==80)timer.Panel.CancelEditor();Pump(50);Save("editor/"+i.ToString("D3"));}
 menu.AnimationsEnabled=false;menu.ShowHome();Pump(100);var r=menu.PixelBounds;b=bubble.PixelBounds;bubble.MovePixels(r.Right-(int)(Theme.LauncherDockInset*dpi)-b.Width,r.Bottom-(int)(Theme.LauncherDockInset*dpi)-b.Height);menu.RestoreCardContour();Pump(50);Save("home");Console.WriteLine("Captured 490 native WPF animation frames and 3 stills with fixture data.");
 }finally{if(menu!=null){menu.Disposing=true;menu.Close();}if(bubble!=null)bubble.Close();preferences.Dispose();app.Shutdown();}}
}
